<?php
namespace App\Services\Ledger;use App\Models\Ledger\TaxFinancialStatementModel;use Core\Helpers\ActorHelper;use Core\Helpers\UuidHelper;use Core\LoggerFactory;use InvalidArgumentException;use PDO;use Throwable;
class TaxFinancialStatementService{
 private const TYPES=['TRIAL_BALANCE','INCOME_STATEMENT','STATEMENT_POSITION','COST_STATEMENT','RETAINED_EARNINGS'];private TaxFinancialStatementModel$model;private$logger;public function __construct(private readonly PDO$db){$this->model=new TaxFinancialStatementModel($db);$this->logger=LoggerFactory::getLogger('service-ledger-tax-financial-statement');}
 public function list(array$f=[]):array{return ActorHelper::enrichActorNames($this->model->list($f),['confirmed_by_name'=>'confirmed_by','updated_by_name'=>'updated_by']);}public function options():array{return['companies'=>$this->model->companies(),'accounts'=>$this->model->accounts()];}public function detail(string$id):?array{$r=$this->model->find($id);if(!$r)return null;$r['lines']=$this->model->lines($id);return ActorHelper::enrichActorNamesRow($r,['confirmed_by_name'=>'confirmed_by','updated_by_name'=>'updated_by']);}
 public function save(array$i):array{$id=trim((string)($i['id']??''));$c=trim((string)($i['company_id']??''));$y=(int)($i['fiscal_year']??0);$t=strtoupper(trim((string)($i['report_type_code']??'')));$org=trim((string)($i['source_organization']??''));$lines=$i['lines']??[];if($c===''||$y<1900||!in_array($t,self::TYPES,true)||$org==='')throw new InvalidArgumentException('회사, 회계연도, 재무제표 유형과 작성기관을 입력해 주세요.');if(!is_array($lines)||$lines===[])throw new InvalidArgumentException('세무 재무제표 행을 한 개 이상 입력해 주세요.');$a=ActorHelper::user();$at=date('Y-m-d H:i:s');$owns=!$this->db->inTransaction();try{if($owns)$this->db->beginTransaction();$current=$id!==''?$this->model->find($id,true):null;if($id!==''&&!$current)throw new InvalidArgumentException('세무 재무제표를 찾을 수 없습니다.');if(($current['status_code']??'')==='CONFIRMED')throw new InvalidArgumentException('확정 자료는 확정취소 후 수정할 수 있습니다.');$dup=$this->model->duplicate($c,$y,$t);if($dup&&(string)$dup['id']!==$id)throw new InvalidArgumentException('동일 회사·회계연도·재무제표 유형이 이미 있습니다.');$base=[':company_id'=>$c,':fiscal_year'=>$y,':report_type_code'=>$t,':source_organization'=>$org,':filing_date'=>$this->nullable($i['filing_date']??null),':note'=>$this->nullable($i['note']??null),':updated_at'=>$at,':updated_by'=>$a];if($current)$this->model->update($id,$base);else{$id=UuidHelper::generate();$this->model->insert($base+[':id'=>$id,':status_code'=>'DRAFT',':created_at'=>$at,':created_by'=>$a]);}$rows=[];foreach(array_values($lines)as$n=>$line){$name=trim((string)($line['item_name']??''));if($name==='')throw new InvalidArgumentException(($n+1).'행의 과목명을 입력해 주세요.');$rows[]=[':id'=>UuidHelper::generate(),':sort_no'=>$n+1,':item_code'=>$this->nullable($line['item_code']??null),':item_name'=>$name,':account_id'=>$this->nullable($line['account_id']??null),':hierarchy_level'=>max(1,min(9,(int)($line['hierarchy_level']??1))),':current_amount'=>(float)($line['current_amount']??0),':prior_amount'=>(float)($line['prior_amount']??0),':note'=>$this->nullable($line['note']??null),':created_at'=>$at,':created_by'=>$a,':updated_at'=>$at,':updated_by'=>$a];}$this->model->replaceLines($id,$rows);if($owns)$this->db->commit();$this->logger->info('세무 재무제표 확정본을 저장했습니다.',['event_code'=>'TAX_FINANCIAL_STATEMENT_SAVED','result'=>'SUCCESS','service'=>self::class,'action'=>'save','actor'=>$a,'target_id'=>$id]);return['success'=>true,'message'=>'세무 재무제표를 저장했습니다.','data'=>$this->detail($id)];}catch(Throwable$e){if($owns&&$this->db->inTransaction())$this->db->rollBack();$this->logFailure($e,'save',$id);throw$e;}}
 public function confirm(string$id,bool$yes):array{$r=$this->model->find($id);if(!$r)throw new InvalidArgumentException('세무 재무제표를 찾을 수 없습니다.');$a=ActorHelper::user();$this->model->confirm($id,$yes,$a,date('Y-m-d H:i:s'));$this->logger->info($yes?'세무 재무제표를 확정했습니다.':'세무 재무제표 확정을 취소했습니다.',['event_code'=>$yes?'TAX_FINANCIAL_STATEMENT_CONFIRMED':'TAX_FINANCIAL_STATEMENT_CONFIRM_CANCELLED','result'=>'SUCCESS','service'=>self::class,'action'=>$yes?'confirm':'cancel-confirm','actor'=>$a,'target_id'=>$id]);return['success'=>true,'message'=>$yes?'세무 재무제표를 확정했습니다.':'확정을 취소했습니다.','data'=>$this->detail($id)];}public function delete(string$id):array{$r=$this->model->find($id);if(!$r)throw new InvalidArgumentException('세무 재무제표를 찾을 수 없습니다.');if($r['status_code']==='CONFIRMED')throw new InvalidArgumentException('확정 자료는 삭제할 수 없습니다.');$this->model->delete($id);$this->logger->info('세무 재무제표를 삭제했습니다.',['event_code'=>'TAX_FINANCIAL_STATEMENT_DELETED','result'=>'SUCCESS','service'=>self::class,'action'=>'delete','actor'=>ActorHelper::user(),'target_id'=>$id]);return['success'=>true,'message'=>'삭제했습니다.'];}
 public function comparison(string$c,int$y,string$t):array{$t=strtoupper($t);if(!in_array($t,self::TYPES,true))throw new InvalidArgumentException('비교할 재무제표 유형을 선택해 주세요.');$doc=$this->model->duplicate($c,$y,$t);if(!$doc||$doc['status_code']!=='CONFIRMED')return['document'=>null,'rows'=>[],'summary'=>['enterprise_amount'=>0,'tax_amount'=>0,'difference_amount'=>0]];$map=['TRIAL_BALANCE'=>'trial-balance','INCOME_STATEMENT'=>'income-statement','STATEMENT_POSITION'=>'statement-position','COST_STATEMENT'=>'construction-cost','RETAINED_EARNINGS'=>'retained-earnings'];$enterprise=(FinancialStatementService::fromPdo($this->db))->report($map[$t],['date_from'=>sprintf('%04d-01-01',$y),'date_to'=>sprintf('%04d-12-31',$y)]);$amounts=[];foreach($enterprise['rows']as$r)$amounts[(string)$r['id']]=(float)($r['current_amount']??$r['ending_balance']??0);$rows=[];$et=$tt=0;foreach($this->model->lines((string)$doc['id'])as$l){$e=$l['account_id']?($amounts[(string)$l['account_id']]??0):0;$tax=(float)$l['current_amount'];$rows[]=$l+['enterprise_amount'=>$e,'tax_amount'=>$tax,'difference_amount'=>$e-$tax,'mapping_status'=>$l['account_id']?'MAPPED':'UNMAPPED'];$et+=$e;$tt+=$tax;}return['document'=>$doc,'rows'=>$rows,'summary'=>['enterprise_amount'=>$et,'tax_amount'=>$tt,'difference_amount'=>$et-$tt]];}
 private function nullable(mixed$v):?string{$v=trim((string)$v);return$v===''?null:$v;}private function logFailure(Throwable$e,string$action,string$id):void{$this->logger->error('세무 재무제표 업무를 완료하지 못했습니다.',['event_code'=>'TAX_FINANCIAL_STATEMENT_FAILED','result'=>$e instanceof InvalidArgumentException?'BLOCKED':'FAILED','service'=>self::class,'action'=>$action,'target_id'=>$id,'error_code'=>$e::class]);}
}
